Save this as `visual-brief-studio.html` and open it in your browser. It runs fully offline, uses localStorage, avoids external assets, and builds all dynamic tile output with DOM text/value updates instead of user-content `innerHTML`.

```html
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Visual Brief Tile Studio</title>
<style>
  :root{
    --bg:#f6f2ea;
    --panel:#fffaf1;
    --panel2:#f0e6d3;
    --ink:#28231c;
    --muted:#6f6456;
    --line:#dacdb8;
    --accent:#8a5b31;
    --accent2:#3f6f65;
    --warn:#9f4d2f;
    --good:#3d7659;
    --shadow:0 14px 38px rgba(48,38,24,.12);
    --radius:22px;
  }

  *{box-sizing:border-box}

  html,body{
    margin:0;
    min-height:100%;
    background:
      radial-gradient(circle at top left, rgba(138,91,49,.13), transparent 32rem),
      linear-gradient(180deg,#fbf7ef 0%,var(--bg) 100%);
    color:var(--ink);
    font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  }

  body{
    padding:12px;
    overflow-x:visible;
  }

  .app{
    width:100%;
    max-width:760px;
    margin:0 auto;
  }

  header{
    border:1px solid var(--line);
    background:rgba(255,250,241,.92);
    border-radius:28px;
    padding:18px;
    box-shadow:var(--shadow);
  }

  .eyebrow{
    display:block;
    font-size:12px;
    letter-spacing:.08em;
    text-transform:uppercase;
    color:var(--accent);
    font-weight:800;
    margin-bottom:10px;
  }

  h1{
    margin:0;
    font-size:32px;
    line-height:1.02;
    letter-spacing:0;
  }

  h1 span{
    display:block;
  }

  .lede{
    margin:12px 0 0;
    color:var(--muted);
    font-size:15px;
    line-height:1.45;
  }

  main{
    display:grid;
    grid-template-columns:1fr;
    gap:12px;
    margin-top:12px;
  }

  .card{
    width:100%;
    min-width:0;
    border:1px solid var(--line);
    background:rgba(255,250,241,.95);
    border-radius:var(--radius);
    padding:14px;
    box-shadow:0 8px 24px rgba(48,38,24,.08);
  }

  .card h2{
    margin:0 0 10px;
    font-size:18px;
    line-height:1.2;
  }

  label{
    display:block;
    margin:12px 0 6px;
    font-size:13px;
    font-weight:800;
    color:#4b4035;
  }

  input, textarea, select, button{
    width:100%;
    max-width:100%;
    font:inherit;
    color:var(--ink);
  }

  input, textarea, select{
    border:1px solid var(--line);
    border-radius:16px;
    background:#fffdf8;
    padding:11px 12px;
    outline:none;
  }

  textarea{
    min-height:82px;
    resize:vertical;
    line-height:1.4;
  }

  input::placeholder,
  textarea::placeholder{
    color:#9b8b78;
    white-space:normal;
  }

  input:focus, textarea:focus, select:focus{
    border-color:rgba(138,91,49,.75);
    box-shadow:0 0 0 3px rgba(138,91,49,.13);
  }

  .grid{
    display:grid;
    grid-template-columns:1fr;
    gap:10px;
  }

  .tile{
    width:100%;
    min-width:0;
    border:1px solid var(--line);
    background:#fffdf8;
    border-radius:18px;
    padding:12px;
  }

  .tileTop{
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap:8px;
    flex-wrap:wrap;
    margin-bottom:8px;
  }

  .tileTitle{
    font-size:14px;
    font-weight:900;
  }

  .badge{
    display:inline-flex;
    max-width:100%;
    align-items:center;
    justify-content:center;
    border-radius:999px;
    padding:6px 9px;
    font-size:12px;
    font-weight:800;
    background:var(--panel2);
    color:#554838;
    overflow-wrap:anywhere;
  }

  .badge.good{
    background:rgba(61,118,89,.12);
    color:var(--good);
  }

  .badge.warn{
    background:rgba(159,77,47,.12);
    color:var(--warn);
  }

  .chipRow{
    display:grid;
    grid-template-columns:1fr;
    gap:8px;
    margin-top:8px;
  }

  .chip{
    border:1px solid var(--line);
    background:#fffaf1;
    border-radius:999px;
    padding:9px 10px;
    font-size:13px;
    font-weight:750;
    line-height:1.2;
    overflow-wrap:anywhere;
  }

  .chip input{
    position:absolute;
    opacity:0;
    pointer-events:none;
