    display:grid;
    grid-template-columns:1fr;
    gap:8px;
    margin:10px 0 0;
  }

  .driftItem{
    border:1px solid var(--line);
    background:#fffdf8;
    border-radius:15px;
    padding:10px;
    font-size:13px;
    line-height:1.35;
