    line-height:1.45;
  }

  .status{
    margin-top:8px;
    color:var(--muted);
    font-size:13px;
    min-height:18px;
  }

  .footerPills{
    display:grid;
    grid-template-columns:1fr;
    gap:8px;
    margin-top:12px;
